  // Filter by category. Pass one or more of: enquiry, feedback, incident, injury, notes, mileage.
  category?: Array<"enquiry" | "feedback" | "incident" | "injury" | "notes" | "mileage">;
  // Filter by client. Tagged notes match exactly; untagged notes match via shift ratios.
  client_id?: number;
  // Filter notes created at or after this ISO8601 UTC datetime (YYYY-MM-DDTHH:MM:SSZ). If the request sends no other filter (created_to, shift_id, staff_id, client_id, shift_date_from / shift_date_to), the API applies a default 90-day window to keep queries off the full history of a large, time-partitioned table; pass this param, or any of those filters, to reach older notes. The MCP tool requires this and rejects values older than 90 days ago. For bulk historical pulls, prefer shift_date_from / shift_date_to.
  created_from: string;
  // Filter notes created at or before this ISO8601 UTC datetime (YYYY-MM-DDTHH:MM:SSZ).
  created_to?: string;
  // Include pagination metadata in response body
  include_metadata?: boolean;
  // Page offset to fetch. Must be 1 or greater.
  page?: number;
  // Number of items to return per page. Must be 1 or greater. Maximum value: 20 (values above are silently capped).
  per_page?: number;
  // Filter by the shift's local calendar date (YYYY-MM-DD), interpreted in the time_zone argument, or the account time zone when none is given. Recommended for bulk historical pulls — uses shifts(start_at) index.
  shift_date_from?: string;
  // Filter by the shift's local calendar date (YYYY-MM-DD), interpreted in the time_zone argument, or the account time zone when none is given.
  shift_date_to?: string;
  // Filter progress notes by shift ID
